<!DOCTYPE html>
<html lang="id">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Verifikasi Peminjaman</title><style>body{background:#f4f6fa;color:#172033;font:16px/1.5 Arial,sans-serif;margin:0;padding:24px}.verification{background:#fff;border:1px solid #dce2ec;margin:8vh auto;max-width:520px;padding:28px}.mark{color:#168458;font-size:13px;font-weight:700;text-transform:uppercase}h1{font-size:24px;margin:10px 0}.data{border-top:1px solid #e5e7eb;margin-top:20px;padding-top:14px}.data p{margin:8px 0}.data span{color:#64748b;display:inline-block;width:130px}</style></head>
<body><main class="verification"><div class="mark">Transaksi terverifikasi</div><h1>Bukti Peminjaman #{{ str_pad((string) $peminjaman->id, 6, '0', STR_PAD_LEFT) }}</h1><div class="data"><p><span>Barang</span><strong>{{ $peminjaman->barang->nama_barang }}</strong></p><p><span>Jumlah</span><strong>{{ $peminjaman->jumlah }} unit</strong></p><p><span>Status</span><strong>{{ ucfirst($peminjaman->status_tampil) }}</strong></p><p><span>Jatuh tempo</span><strong>{{ $peminjaman->tanggal_kembali_rencana->format('d F Y') }}</strong></p></div></main></body>
</html>
